independent_probe_source:
extends SceneTree
const P=preload("res://scripts/presentation/board_depth_projection.gd")
const C=preload("res://scripts/data/board_trial_config.gd")
class Held extends "res://scripts/board_depth.gd":
	func _brain(_actor: Dictionary,_delta: float) -> void: pass
var max_numeric_delta:=0.0
var checks:=0
var failures:=0
var labels:=[]
var cases:=[]
var output:="/tmp/qa07-perspective-20261017/probes-source.json"
var baseline:="res://tests/board-trial-runtime/board-balance-20261009-natural.json"
func _initialize(): call_deferred("run")
func check(ok: bool,label: String):
	checks+=1
	if not ok:
		failures+=1
		if labels.size()<20: labels.append(label)
func ref_point(g: Vector2) -> Vector2:
	# Independently parameterized from the four calibrated trapezoid corners.
	var r:=1059.84/1288.0
	var t: float=(g.y/7.0)*r/(1.0-(1.0-r)*g.y/7.0)
	return Vector2(348.16-114.08*t+(1059.84+228.16*t)*g.x/12.0,319.76+414.0*t)
func ref_scale(g: Vector2) -> float:
	var t: float=(float(ref_point(g).y)-319.76)/414.0
	return .9*(1059.84+228.16*t)/1288.0
func adjacent(value: float,delta: int) -> float:
	var bytes:=PackedByteArray();bytes.resize(4);bytes.encode_float(0,value)
	bytes.encode_u32(0,bytes.decode_u32(0)+delta)
	return bytes.decode_float(0)
func exact_boundary():
	var tested:=0
	for i in 277:
		var y: float=Vector2(0,320.0+float(i)*1.492).y
		var t: float=(y-319.76)/414.0
		var row: int=floori(7.0*t/(1059.84/1288.0+(1.0-1059.84/1288.0)*t))
		for column in 13:
			var x: float=Vector2(348.16-114.08*t+(1059.84+228.16*t)*column/12.0,0).x
			for side in [-1,0,1]:
				var q:=Vector2(adjacent(x,side) if side!=0 else x,y)
				var col: int=column-1 if side<0 else column
				var expected:=Vector2i(col,row) if col>=0 and col<12 else Vector2i(-1,-1)
				check(P.cell_at(q)==expected,"one-ULP column "+str([i,column,side,q,P.cell_at(q),expected]))
				tested+=1
	for row in 8:
		var edge:=ref_point(Vector2(6.5,row))
		for side in [-1,0,1]:
			var q:=Vector2(edge.x,adjacent(edge.y,side) if side!=0 else edge.y)
			var picked_row: int=row-1 if side<0 else row
			var expected:=Vector2i(6,picked_row) if picked_row>=0 and picked_row<7 else Vector2i(-1,-1)
			check(P.cell_at(q)==expected,"one-ULP row "+str([row,side,q,P.cell_at(q),expected]))
			tested+=1
	check(P.cell_at(Vector2(120,110)+Vector2(200,470)*.92)==Vector2i(0,4),"author original supposed forest point is actually playable")
	check(P.cell_at(Vector2(120,110)+Vector2(100,470)*.92)==Vector2i(-1,-1),"replacement forest point actually outside")
	cases.append({"case":"independent_calibrated_line_one_ULP","samples":tested,"no_epsilon_cell_assertions":true})
func equivalent(a,b) -> bool:
	if typeof(a) in [TYPE_INT,TYPE_FLOAT] and typeof(b) in [TYPE_INT,TYPE_FLOAT]:
		var delta:=absf(float(a)-float(b))
		max_numeric_delta=maxf(max_numeric_delta,delta)
		return delta<1e-10
	if typeof(a)!=typeof(b): return false
	if a is Dictionary:
		if a.size()!=b.size():return false
		for key in a:
			if not b.has(key) or not equivalent(a[key],b[key]):return false
		return true
	if a is Array:
		if a.size()!=b.size():return false
		for i in a.size():
			if not equivalent(a[i],b[i]):return false
		return true
	return a==b
func natural(sim_speed: int):
	var g=load("res://scenes/board_trial.tscn").instantiate()
	root.add_child(g);g.set_process(false);g.load_formation("A");g.start_battle();g.speed=sim_speed
	var observations:=0
	var moving:=0
	var vertical:=0
	var max_error:=0.0
	var frozen:={}
	var paused_once:=false
	while g.phase==g.Phase.BATTLE and g.elapsed<60:
		g.step(C.STEP/sim_speed)
		for a in g.actors:
			if not is_instance_valid(a.node): continue
			if a.dead:
				if frozen.has(a.id): check(a.node.position==frozen[a.id].position and a.node.scale==frozen[a.id].scale,"dead visual stays frozen "+a.id)
				else: frozen[a.id]={"position":a.node.position,"scale":a.node.scale}
				continue
			var grid:=Vector2(a.cell)+Vector2(.5,.5)
			if not a.move.is_empty():
				moving+=1
				grid=Vector2(a.move.from).lerp(Vector2(a.move.to),a.move.time/.5)+Vector2(.5,.5)
				if a.move.from.y!=a.move.to.y: vertical+=1
				check(a.move.duration==.5,"real natural movement duration")
			var error: float=a.node.position.distance_to(ref_point(grid));max_error=maxf(max_error,error)
			check(error<.0003,"live natural foot follows independent calibrated homography "+a.id)
			check(absf(a.node.scale.x-ref_scale(grid))<.0000002,"live natural body scale follows independent depth "+a.id)
			check(a.node.z_index==int(a.node.position.y),"live natural depth ordering "+a.id)
			observations+=1
		if not paused_once and g.elapsed>=2:
			g.toggle_pause();var before=g.report().duplicate(true);g.step(9)
			check(g.report()==before,"extra natural pause freezes report")
			g.toggle_pause();paused_once=true
	var gold=JSON.parse_string(FileAccess.get_file_as_string(baseline))
	var expected=gold.cases.filter(func(a): return a.profile=="bear" and a.formation=="A")[0].report
	check(g.phase==g.Phase.RESULT and equivalent(g.report(),expected),"actual natural A entire historical report matches with 1e-10 numeric serialization tolerance")
	check(moving>100 and vertical>0 and frozen.size()>0,"live trace includes movement depth changes and real deaths")
	cases.append({"case":"independent_live_every_STEP","speed":sim_speed,"observations":observations,"moving_samples":moving,"vertical_samples":vertical,"frozen_deaths":frozen.size(),"max_screen_error":max_error,"report":g.report()})
	g.free()
func moving_projectile():
	var g=Held.new();root.add_child(g);g.set_process(false)
	var hunter=g._record("wild_hunter");var target=g._record("E5")
	var index:=0
	for a in g.actors:
		if a.id in [hunter.id,target.id]: continue
		g._set_cell(a,Vector2i(index,0));index+=1
	g._set_cell(hunter,Vector2i(2,2));g._set_cell(target,Vector2i(5,2))
	g.start_battle();g._attack(hunter,target)
	for i in 200:
		g.step(C.STEP)
		if not g.combat.missiles.is_empty(): break
	check(g.combat.missiles.size()==1,"true projectile released before target movement")
	if g.combat.missiles.size()!=1: g.free();return
	var missile=g.combat.missiles[0];var began: float=g.elapsed;var hp: float=target.node.health
	check(g._move(target,Vector2i(5,3)),"target begins legal real half-second downward step")
	var samples:=0
	while not g.combat.missiles.is_empty() and g.elapsed<began+1:
		g.step(C.STEP)
		var grid:=Vector2(5.5,2.5+target.move.time/.5)
		var expected_aim:=ref_point(grid)+Vector2(0,-35*ref_scale(grid))
		check(g.combat.target_point(target.node).distance_to(expected_aim)<.0003,"moving target contact anchor follows continuous projected body")
		check(missile.position.distance_to(missile.from.lerp(expected_aim,minf(1,missile.time/.25)))<.0003,"true missile tracks continuously moving scaled target")
		samples+=1
	check(samples==30 and absf(g.elapsed-began-.25)<1e-10,"real flight is exactly original 30 STEP quarter second")
	check(target.node.health==hp-hunter.damage and g.combat.counts.hits==1,"one actual original damage application")
	check(not target.move.is_empty() and is_equal_approx(target.move.time,.25),"contact occurs halfway through real target step")
	cases.append({"case":"independent_continuous_target_projectile","samples":samples,"flight_seconds":g.elapsed-began,"damage":hp-target.node.health})
	g.free()
func run():
	for arg in OS.get_cmdline_user_args():
		if arg.begins_with("--output="):output=arg.trim_prefix("--output=")
		if arg.begins_with("--baseline="):baseline=arg.trim_prefix("--baseline=")
	exact_boundary();natural(1);natural(2);moving_projectile()
	check(cases.size()==4,"all four independent groups completed")
	var f=FileAccess.open(output,FileAccess.WRITE)
	f.store_string(JSON.stringify({"checks":checks,"failures":failures,"first_failure_labels":labels,"cases":cases,"groups":cases.size(),"native_mouse_or_rendered_review":false,"max_numeric_baseline_delta":max_numeric_delta},"\t"))
	print("QA07_PERSPECTIVE checks=",checks," groups=",cases.size()," failures=",failures," first=",labels)
	quit(1 if failures else 0)
